/**
 * Navigation JS - Navigation bar functionality
 */

/** Navigation link definitions */
var NAV_ITEMS = [
    { title: 'Home', href: 'index.html', icon: '&#8962;' },
    { title: 'Dashboard', href: 'dashboard.html', icon: '&#9776;' },
    { title: 'Audit Log', href: 'audit-log.html', icon: '&#128466;' }
];

var navAnimationTimeoutId = null;

/**
 * Initialize the navigation bar
 */
function initNavigation() {
    var navBar = document.getElementById('navigation-bar');
    if (!navBar) return;

    renderNavigationMenu();
    setActiveNavItem();
    initProfileIcon();

    // Restore collapsed state from storage
    if (localStorage.getItem('nav_collapsed') === 'true') {
        navBar.classList.add('collapsed');
        document.body.classList.add('nav-collapsed');
    }

    // Listen for resize to handle mobile
    window.addEventListener('resize', handleResize);
    handleResize();
}

/**
 * Render navigation menu items
 */
function renderNavigationMenu() {
    var navBar = document.getElementById('navigation-bar');
    if (!navBar) return;

    var html = '';

    // Nav header with logo and toggle
    html += '<div class="nav-header">';
    html += '  <span class="nav-logo-text">Michelin</span>';
    html += '  <button class="nav-toggle" id="nav-toggle-btn" aria-label="Toggle navigation">&#9776;</button>';
    html += '</div>';

    // Nav menu links
    html += '<ul class="nav-menu">';
    for (var i = 0; i < NAV_ITEMS.length; i++) {
        var item = NAV_ITEMS[i];
        html += '<li class="nav-item">';
        html += '  <a href="' + item.href + '" class="nav-link" data-page="' + item.href + '">';
        html += '    <span class="nav-icon">' + item.icon + '</span>';
        html += '    <span class="nav-text">' + item.title + '</span>';
        html += '  </a>';
        html += '</li>';
    }
    html += '</ul>';

    navBar.innerHTML = html;

    // Attach toggle listener
    var toggleBtn = document.getElementById('nav-toggle-btn');
    if (toggleBtn) {
        toggleBtn.addEventListener('click', toggleNavigation);
    }

    // Attach click listeners with auth check
    var links = navBar.querySelectorAll('.nav-link');
    for (var j = 0; j < links.length; j++) {
        links[j].addEventListener('click', handleNavClick);
    }
}

/**
 * Toggle navigation bar collapsed/expanded state
 */
function toggleNavigation() {
    var navBar = document.getElementById('navigation-bar');
    if (!navBar) return;

    setNavAnimationEnabled(true);

    var isCollapsed = navBar.classList.toggle('collapsed');
    document.body.classList.toggle('nav-collapsed', isCollapsed);
    localStorage.setItem('nav_collapsed', isCollapsed);

    // On mobile, toggle the open class instead
    if (window.innerWidth <= 768) {
        navBar.classList.toggle('open');
        navBar.classList.remove('collapsed');
        document.body.classList.remove('nav-collapsed');
    }
}

/**
 * Enable transition classes only during explicit user toggle interaction.
 * This prevents layout/state restoration from repeatedly replaying animations.
 * @param {boolean} enabled - Whether to enable nav animation
 */
function setNavAnimationEnabled(enabled) {
    var navBar = document.getElementById('navigation-bar');
    if (!navBar) return;

    if (navAnimationTimeoutId) {
        clearTimeout(navAnimationTimeoutId);
        navAnimationTimeoutId = null;
    }

    if (enabled) {
        navBar.classList.add('nav-animate');
        document.body.classList.add('nav-animate');
        navAnimationTimeoutId = setTimeout(function() {
            navBar.classList.remove('nav-animate');
            document.body.classList.remove('nav-animate');
            navAnimationTimeoutId = null;
        }, 350);
    } else {
        navBar.classList.remove('nav-animate');
        document.body.classList.remove('nav-animate');
    }
}

/**
 * Set active navigation item based on current page
 */
function setActiveNavItem() {
    var currentPage = window.location.pathname.split('/').pop() || 'index.html';
    var links = document.querySelectorAll('#navigation-bar .nav-link');
    for (var i = 0; i < links.length; i++) {
        var linkPage = links[i].getAttribute('data-page');
        if (linkPage === currentPage) {
            links[i].classList.add('active');
        } else {
            links[i].classList.remove('active');
        }
    }
}

/**
 * Handle navigation link click
 * @param {Event} event - Click event
 */
function handleNavClick(event) {
    if (!window.AppUtils.isAuthenticated()) {
        event.preventDefault();
        window.location.href = 'login.html';
        return;
    }

    // On mobile, close nav after clicking
    if (window.innerWidth <= 768) {
        var navBar = document.getElementById('navigation-bar');
        if (navBar) {
            navBar.classList.remove('open');
        }
    }
}

/**
 * Initialize profile icon
 */
function initProfileIcon() {
    var container = document.getElementById('profile-icon-container');
    if (!container) return;

    var html = '<div class="profile-icon" id="profile-icon" aria-label="Settings">';
    html += '  <span class="profile-icon-text">U</span>';
    html += '</div>';

    container.innerHTML = html;

    var icon = document.getElementById('profile-icon');
    if (icon) {
        icon.addEventListener('click', handleProfileClick);
    }

    // Try to load the user's profile picture
    if (window.AppUtils.isAuthenticated() && window.Auth && window.Auth.getCurrentUser) {
        window.Auth.getCurrentUser().then(function(user) {
            if (user && user.profile_picture) {
                updateProfileIcon(user.profile_picture);
            }
            if (user && user.name) {
                var textEl = container.querySelector('.profile-icon-text');
                if (textEl) {
                    textEl.textContent = user.name.charAt(0).toUpperCase();
                }
            }
        }).catch(function() {
            // Silently fail — keep default icon
        });
    }
}

/**
 * Handle profile icon click (navigate to settings)
 */
function handleProfileClick() {
    if (!window.AppUtils.isAuthenticated()) {
        window.location.href = 'login.html';
        return;
    }
    window.location.href = 'settings.html';
}

/**
 * Update profile icon with user's picture
 * @param {string} imageUrl - Profile picture URL
 */
function updateProfileIcon(imageUrl) {
    var icon = document.getElementById('profile-icon');
    if (!icon || !imageUrl) return;

    icon.innerHTML = '<img src="' + imageUrl + '" alt="Profile">';
}

/**
 * Handle mobile navigation toggle
 */
function handleMobileNavToggle() {
    var navBar = document.getElementById('navigation-bar');
    if (!navBar) return;
    navBar.classList.toggle('open');
}

/**
 * Handle window resize for responsive navigation
 */
function handleResize() {
    var navBar = document.getElementById('navigation-bar');
    var mobileToggle = document.getElementById('mobile-nav-toggle');
    if (!navBar) return;

    if (window.innerWidth <= 768) {
        // Mobile: remove collapsed, show mobile toggle
        navBar.classList.remove('collapsed');
        document.body.classList.remove('nav-collapsed');
        if (!mobileToggle) {
            var btn = document.createElement('button');
            btn.id = 'mobile-nav-toggle';
            btn.className = 'mobile-nav-toggle';
            btn.setAttribute('aria-label', 'Open navigation');
            btn.innerHTML = '&#9776;';
            btn.addEventListener('click', handleMobileNavToggle);
            document.body.appendChild(btn);
        }
    } else {
        // Desktop: remove open, remove mobile toggle
        navBar.classList.remove('open');
        if (mobileToggle) {
            mobileToggle.remove();
        }
        // Restore collapsed state
        if (localStorage.getItem('nav_collapsed') === 'true') {
            navBar.classList.add('collapsed');
            document.body.classList.add('nav-collapsed');
        }
    }
}

